import type { Metadata } from "next";
import { Suspense } from "react";
import { getTranslations } from "next-intl/server";

import { AuthCard } from "@/components/auth/auth-card";
import { ResetPasswordForm } from "@/components/auth/reset-password-form";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("auth-password-reset");
  return {
    title: t("resetPage.metadata.title"),
    description: t("resetPage.metadata.description"),
  };
}

export default async function ResetPasswordPage() {
  const t = await getTranslations("auth-password-reset");

  return (
    <AuthCard
      title={t("resetPage.card.title")}
      description={t("resetPage.card.description")}
    >
      {/* useSearchParams (inside ResetPasswordForm) requires a Suspense
          boundary — it opts the subtree out of full static rendering. */}
      <Suspense
        fallback={
          <div className="text-center text-sm text-muted-foreground">
            {t("resetPage.loading")}
          </div>
        }
      >
        <ResetPasswordForm />
      </Suspense>
    </AuthCard>
  );
}

"use client";

/**
 * Email-only form that starts the password reset flow through
 * Better-Auth's `requestPasswordReset`. `redirectTo` is where the
 * emailed link lands: `/reset-password?token=...` on a valid token,
 * `/reset-password?error=INVALID_TOKEN` on an expired or invalid one.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";

import { authClient } from "@intelligo-dev/auth/client";

import { Link } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Spinner } from "@/components/ui/spinner";
import {
  forgotPasswordSchema,
  type ForgotPasswordInput,
} from "@/lib/auth-validation";

export function ForgotPasswordForm() {
  const t = useTranslations("auth-password-reset");
  const [formError, setFormError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ForgotPasswordInput>({
    resolver: zodResolver(forgotPasswordSchema),
  });

  async function onSubmit(data: ForgotPasswordInput) {
    try {
      setFormError(null);
      setIsLoading(true);

      const result = await authClient.requestPasswordReset({
        email: data.email,
        redirectTo: "/reset-password",
      });

      if (result.error) {
        setFormError(result.error.message ?? t("forgotForm.errors.unexpected"));
        setIsLoading(false);
        return;
      }

      setSuccess(true);
      setIsLoading(false);
    } catch (error) {
      console.error("Forgot password error:", error);
      setFormError(t("forgotForm.errors.unexpected"));
      setIsLoading(false);
    }
  }

  if (success) {
    return (
      <div className="space-y-4">
        <Alert>
          <AlertDescription>{t("forgotForm.successMessage")}</AlertDescription>
        </Alert>
        <Button
          variant="outline"
          className="w-full"
          render={<Link href="/login" />}
          nativeButton={false}
        >
          {t("forgotForm.backToLogin")}
        </Button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate className="space-y-4">
      {formError && (
        <Alert variant="destructive">
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      )}

      <Field data-invalid={errors.email ? true : undefined}>
        <FieldLabel htmlFor="email">{t("forgotForm.emailLabel")}</FieldLabel>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          disabled={isLoading}
          aria-invalid={errors.email ? true : undefined}
          aria-describedby={errors.email ? "email-error" : undefined}
          {...register("email")}
        />
        {errors.email && (
          <FieldError id="email-error">
            {t(`validation.${errors.email.message}`)}
          </FieldError>
        )}
      </Field>

      <Button
        type="submit"
        className="w-full"
        disabled={isLoading}
        aria-busy={isLoading || undefined}
      >
        {isLoading ? (
          <>
            <Spinner data-icon="inline-start" />
            {t("forgotForm.submitting")}
          </>
        ) : (
          t("forgotForm.submit")
        )}
      </Button>

      <p className="text-center text-sm text-muted-foreground">
        {t("forgotForm.rememberPassword")}{" "}
        <Link
          href="/login"
          className="font-medium text-primary hover:text-primary/80"
        >
          {t("forgotForm.logInLink")}
        </Link>
      </p>
    </form>
  );
}

"use client";

/**
 * Password reset completion form, reached from the emailed link.
 * Better-Auth's `/reset-password/:token` redirect appends
 * `?token=<value>` on a valid token or `?error=INVALID_TOKEN` /
 * `?error=TOKEN_EXPIRED` otherwise, so both states are read from the
 * search params.
 */

import { useState } from "react";
import { useSearchParams } from "next/navigation";
import { useTranslations } from "next-intl";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";

import { authClient } from "@intelligo-dev/auth/client";

import { useRouter } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Spinner } from "@/components/ui/spinner";
import {
  resetPasswordSchema,
  type ResetPasswordInput,
} from "@/lib/auth-validation";

export function ResetPasswordForm() {
  const t = useTranslations("auth-password-reset");
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get("token");
  const linkError = searchParams.get("error");

  const [formError, setFormError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ResetPasswordInput>({
    resolver: zodResolver(resetPasswordSchema),
  });

  async function onSubmit(data: ResetPasswordInput) {
    if (!token) {
      setFormError(t("resetForm.errors.invalidLink"));
      return;
    }

    try {
      setFormError(null);
      setIsLoading(true);

      const result = await authClient.resetPassword({
        newPassword: data.password,
        token,
      });

      if (result.error) {
        setFormError(result.error.message ?? t("resetForm.errors.invalidLink"));
        setIsLoading(false);
        return;
      }

      router.push("/login?reset=success");
    } catch (error) {
      console.error("Reset password error:", error);
      setFormError(t("resetForm.errors.invalidLink"));
      setIsLoading(false);
    }
  }

  if (!token || linkError) {
    return (
      <Alert variant="destructive">
        <AlertDescription>
          {t("resetForm.errors.invalidLinkFromForgotPage")}
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate className="space-y-4">
      {formError && (
        <Alert variant="destructive">
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      )}

      <Field data-invalid={errors.password ? true : undefined}>
        <FieldLabel htmlFor="password">
          {t("resetForm.passwordLabel")}
        </FieldLabel>
        <Input
          id="password"
          type="password"
          autoComplete="new-password"
          disabled={isLoading}
          aria-invalid={errors.password ? true : undefined}
          aria-describedby={errors.password ? "password-error" : undefined}
          {...register("password")}
        />
        {errors.password && (
          <FieldError id="password-error">
            {t(`validation.${errors.password.message}`)}
          </FieldError>
        )}
      </Field>

      <Field data-invalid={errors.confirmPassword ? true : undefined}>
        <FieldLabel htmlFor="confirmPassword">
          {t("resetForm.confirmPasswordLabel")}
        </FieldLabel>
        <Input
          id="confirmPassword"
          type="password"
          autoComplete="new-password"
          disabled={isLoading}
          aria-invalid={errors.confirmPassword ? true : undefined}
          aria-describedby={
            errors.confirmPassword ? "confirm-password-error" : undefined
          }
          {...register("confirmPassword")}
        />
        {errors.confirmPassword && (
          <FieldError id="confirm-password-error">
            {t(`validation.${errors.confirmPassword.message}`)}
          </FieldError>
        )}
      </Field>

      <Button
        type="submit"
        className="w-full"
        disabled={isLoading}
        aria-busy={isLoading || undefined}
      >
        {isLoading ? (
          <>
            <Spinner data-icon="inline-start" />
            {t("resetForm.submitting")}
          </>
        ) : (
          t("resetForm.submit")
        )}
      </Button>
    </form>
  );
}

